// ONS-07 — the env alias table is CFG's, generated by agent-os (ONS-02) into
// ./generated/config.env.json and vendored by scripts/sync-cfg-schema.mjs.
// Rows: `derived` paths take AGENT_OS_ + the upper-cased path; `rows` give
// [canonical|null, [legacyName, coercer]..., {extras}?] (null keeps the derived
// name). Never hand-edit an alias here; change it in agent-os and re-vendor.
import { readFileSync } from 'node:fs';

const CFG_ENV = JSON.parse(readFileSync(new URL('./generated/config.env.json', import.meta.url), 'utf8'));

const COERCERS = {
  identity: value => value,
  bool_alias(value) {
    const lower = value.trim().toLowerCase();
    if (lower === 'true' || lower === '1') return 'true';
    if (lower === 'false' || lower === '0' || lower === '') return 'false';
    return value;
  },
  bool_alias_postgres_runtime: value => (value.trim().toLowerCase() === 'on' ? 'postgres' : 'sqlite'),
};

const deriveCanonical = path => `AGENT_OS_${path.replace(/[^A-Za-z0-9]+/g, '_').toUpperCase()}`;

function coercer(name) {
  const fn = COERCERS[name];
  if (!fn) throw new Error(`config.env.json: unknown env coercer ${name}`);
  return fn;
}

// Rows this reader does not apply in the env layer: `profile` is chosen before
// the cascade runs (blank means unset, and it selects the overlay file), and a
// row with positional aliases (`OAUTH_BROKER_URL` -> endpoints[0]) maps a
// process-env contract onto list positions that this reader consumes straight
// from process.env.
const PROFILE_PATH = 'profile';
const isPositional = row => row.some(item => item?.positional_aliases);

export const ENV_ALIASES = {
  ...Object.fromEntries(CFG_ENV.derived.filter(path => path !== PROFILE_PATH)
    .map(path => [path, { canonical: deriveCanonical(path), aliases: [] }])),
  ...Object.fromEntries(Object.entries(CFG_ENV.rows)
    .filter(([path, row]) => path !== PROFILE_PATH && !isPositional(row))
    .map(([path, [canonical, ...legacy]]) => [path, {
      canonical: canonical ?? deriveCanonical(path),
      aliases: legacy.map(([name, coerce]) => [name, coercer(coerce)]),
    }])),
};

const APP_ENV_SUFFIXES = { MODE: 'mode', SUBSCRIBES: 'subscribes', CONTRACT_VERSION: 'contract_version' };
const APP_ENV_PREFIX = 'AGENT_OS_APPS_';

// `AGENT_OS_APPS_<ID>_<MODE|SUBSCRIBES|CONTRACT_VERSION>` registers an app that
// no file declares; the id is the lower-cased, dash-joined segment.
export function dynamicAppEnvAliases(env) {
  const out = [];
  for (const envName of Object.keys(env).sort()) {
    if (!envName.startsWith(APP_ENV_PREFIX)) continue;
    const tail = envName.slice(APP_ENV_PREFIX.length);
    for (const [suffix, leaf] of Object.entries(APP_ENV_SUFFIXES)) {
      const marker = `_${suffix}`;
      if (!tail.endsWith(marker) || tail.length === marker.length) continue;
      const appId = tail.slice(0, -marker.length).toLowerCase().replaceAll('_', '-');
      out.push([`apps.${appId}.${leaf}`, { canonical: envName, aliases: [], appId, writePath: ['apps', appId, leaf] }]);
      break;
    }
  }
  return out;
}

// App ids mentioned by `AGENT_OS_APPS_*` env aliases.
export const dynamicAppEnvIds = env => new Set(dynamicAppEnvAliases(env).map(([, info]) => info.appId));
